<style>
.atlas-docentes{--ad-navy:#143764;--ad-border:#e1e8f1;--ad-muted:#6e7d90;color:#24364d;font-size:14px}
.atlas-docentes *{box-sizing:border-box}.atlas-docentes .ad-heading{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:16px;margin:0 0 22px}.atlas-docentes h2{font-size:24px;color:var(--ad-navy);margin:0 0 6px;font-weight:750}.atlas-docentes .ad-subtitle{margin:0;color:var(--ad-muted)}.atlas-docentes .ad-card{background:#fff;border:1px solid var(--ad-border);border-radius:13px;overflow:hidden;margin-bottom:22px;box-shadow:0 3px 14px rgba(20,55,100,.04)}.atlas-docentes .ad-card-head{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:16px 20px;background:#f9fbfe;border-bottom:1px solid var(--ad-border)}.atlas-docentes .ad-card-body{padding:20px}.atlas-docentes .ad-count{color:var(--ad-muted);white-space:nowrap}.atlas-docentes .ad-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.atlas-docentes .ad-grid.two{grid-template-columns:repeat(2,minmax(0,1fr))}.atlas-docentes .ad-grid.four{grid-template-columns:repeat(4,minmax(0,1fr))}.atlas-docentes .ad-field{min-width:0}.atlas-docentes label{display:block;margin-bottom:7px;font-weight:650;font-size:13px}.atlas-docentes input,.atlas-docentes select,.atlas-docentes textarea{width:100%;min-height:43px;padding:9px 12px;border:1px solid #d5dfeb;border-radius:8px;background:#fff;color:#24364d;font:inherit}.atlas-docentes input:focus,.atlas-docentes select:focus{outline:none;border-color:#6a9bce;box-shadow:0 0 0 3px rgba(40,108,178,.1)}.atlas-docentes .ad-actions{display:flex;justify-content:flex-end;align-items:center;gap:10px;flex-wrap:wrap;margin-top:18px}.atlas-docentes .ad-btn{display:inline-flex;justify-content:center;align-items:center;gap:7px;min-height:39px;padding:8px 14px;border:1px solid #d4dfed;border-radius:8px;background:#fff;color:var(--ad-navy);text-decoration:none;font-size:13px;font-weight:650;cursor:pointer}.atlas-docentes .ad-btn.primary{background:var(--ad-navy);color:white;border-color:var(--ad-navy)}.atlas-docentes .ad-btn.danger{color:#ad3535;border-color:#eccaca}.atlas-docentes .ad-btn:hover{filter:brightness(.94)}.atlas-docentes .ad-table-wrap{overflow-x:auto}.atlas-docentes table{width:100%;border-collapse:collapse;font-size:13px}.atlas-docentes th{padding:14px 16px;text-align:left;background:#f5f8fc;color:#4e627b;white-space:nowrap}.atlas-docentes td{padding:14px 16px;border-top:1px solid #edf1f6;vertical-align:middle}.atlas-docentes tr:hover td{background:#fbfcfe}.atlas-docentes .ad-tag{display:inline-block;border-radius:25px;padding:5px 10px;font-size:11px;font-weight:700;background:#e5f5ec;color:#187246}.atlas-docentes .ad-tag.off{background:#f0f2f5;color:#667487}.atlas-docentes .ad-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-bottom:22px}.atlas-docentes .ad-stat{background:white;border:1px solid var(--ad-border);border-radius:12px;padding:20px}.atlas-docentes .ad-stat strong{display:block;font-size:30px;color:var(--ad-navy);margin-top:9px}.atlas-docentes .ad-muted{color:var(--ad-muted)}.atlas-docentes .ad-alert{padding:12px 15px;margin-bottom:18px;border-radius:9px;background:#e8f6ed;color:#17623b}.atlas-docentes .ad-alert.error{background:#fff0f0;color:#a12f2f}.atlas-docentes .ad-data{display:grid;grid-template-columns:170px 1fr;gap:0;margin:0}.atlas-docentes .ad-data dt,.atlas-docentes .ad-data dd{padding:10px 6px;border-bottom:1px solid #edf1f6;margin:0}.atlas-docentes .ad-data dt{color:var(--ad-muted)}.atlas-docentes .ad-empty{text-align:center;color:var(--ad-muted);padding:30px!important}.atlas-docentes .pagination{display:flex;gap:5px;flex-wrap:wrap;list-style:none}.atlas-docentes .ad-footer{padding:14px 20px;border-top:1px solid var(--ad-border)}
@media(max-width:950px){.atlas-docentes .ad-grid.four,.atlas-docentes .ad-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.atlas-docentes .ad-grid,.atlas-docentes .ad-grid.two,.atlas-docentes .ad-grid.four,.atlas-docentes .ad-stats{grid-template-columns:1fr}.atlas-docentes .ad-card-body{padding:15px}.atlas-docentes .ad-data{grid-template-columns:40% 60%}.atlas-docentes .ad-actions{justify-content:flex-start}}
.atlas-docentes .ad-modal-overlay[hidden]{display:none!important}.atlas-docentes .ad-modal-overlay{position:fixed;inset:0;background:rgba(10,24,44,.62);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px}.atlas-docentes .ad-modal{width:min(100%,440px);padding:28px;background:#fff;border-radius:16px;box-shadow:0 20px 60px rgba(0,0,0,.24)}.atlas-docentes .ad-modal h3{color:var(--ad-navy);font-size:21px;margin:12px 0}.atlas-docentes .ad-modal p{color:#53657a;line-height:1.6}.atlas-docentes .ad-modal-icon{font-size:27px;color:#bc3c3c}.atlas-docentes .ad-modal-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:24px}body.ad-modal-open{overflow:hidden}
</style>
